//! The destination guard, checked against the pinned reference's own answers.
//!
//! `tests/fixtures/phase5a/oracle.json` is generated by
//! `parity/tools/gen_phase5a_fixtures.py` running the archive's code, so every acceptance,
//! refusal and message here is the oracle's verdict — not an expectation written by hand.
//! A divergence fails this test instead of reaching an upstream.

use serde_json::Value;

fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/phase5a/oracle.json"
    );
    let text = std::fs::read_to_string(path).expect("the phase-5A fixture file exists");
    serde_json::from_str(&text).expect("the phase-5A fixture file is JSON")
}

#[test]
fn every_base_url_verdict_matches_the_reference() {
    let fixtures = oracle();
    let cases = fixtures["base_url_cases"].as_array().expect("cases");
    assert!(cases.len() >= 15, "the fixture must carry the full table");
    for case in cases {
        let value = case["value"].as_str().expect("value");
        let allow = case["allow_internal_http"].as_bool().expect("allow flag");
        let expected_ok = case["ok"].as_bool().expect("verdict");
        let result = mcp_server_rs::sources::guard::checked_base_url(value, allow);
        assert_eq!(
            result.is_ok(),
            expected_ok,
            "checked_base_url({value:?}, {allow}) disagreed with the reference"
        );
        if let Err(error) = result {
            assert_eq!(
                error.to_string(),
                case["message"].as_str().expect("message"),
                "{value:?}"
            );
        }
    }
}

#[test]
fn every_enforce_verdict_matches_the_reference() {
    let fixtures = oracle();
    for case in fixtures["enforce_cases"].as_array().expect("cases") {
        let url = case["base_url"].as_str().expect("base_url");
        let allow_internal_http = case["allow_internal_http"].as_bool().expect("flag");
        let allowed: Vec<&str> = case["allowed"]
            .as_array()
            .expect("allowed")
            .iter()
            .map(|v| v.as_str().expect("entry"))
            .collect();
        let expected_ok = case["ok"].as_bool().expect("verdict");
        let result = mcp_server_rs::sources::guard::enforce(
            url,
            allow_internal_http,
            allowed.iter().copied(),
        );
        assert_eq!(
            result.is_ok(),
            expected_ok,
            "enforce({url:?}, {allowed:?}) disagreed with the reference"
        );
        if let Err(error) = result {
            assert_eq!(
                error.to_string(),
                case["message"].as_str().expect("message")
            );
        }
    }
}

#[test]
fn every_host_allowed_verdict_matches_the_reference() {
    let fixtures = oracle();
    for case in fixtures["host_cases"].as_array().expect("cases") {
        let url = case["base_url"].as_str().expect("base_url");
        let allowed: Vec<&str> = case["allowed"]
            .as_array()
            .expect("allowed")
            .iter()
            .map(|v| v.as_str().expect("entry"))
            .collect();
        assert_eq!(
            mcp_server_rs::sources::guard::host_allowed(url, allowed.iter().copied()),
            case["ok"].as_bool().expect("verdict"),
            "host_allowed({url:?}, {allowed:?})"
        );
    }
}

#[test]
fn every_address_literal_verdict_matches_the_reference() {
    let fixtures = oracle();
    for case in fixtures["ip_cases"].as_array().expect("cases") {
        let host = case["host"].as_str().expect("host");
        assert_eq!(
            mcp_server_rs::sources::guard::is_ip_literal(host),
            case["ip"].as_bool().expect("verdict"),
            "is_ip_literal({host:?})"
        );
    }
}
